values.value:
{
  "fields": [
    {
      "apiName": "freight_incoterms",
      "label": "Trans.in offer?",
      "type": "picklist",
      "readOnly": true,
      "formula": "(w_SSSB_w_beam_trans_in_offer_rm == 'F.O.R (Freight on Road)' || w_SSDB_w_beam_trans_in_offer_rm == 'F.O.R (Freight on Road)' || w_DSSB_w_beam_trans_in_offer_rm == 'F.O.R (Freight on Road)' || w_DSDB_w_beam_trans_in_offer_rm == 'F.O.R (Freight on Road)' || Thrie_SSSB_trans_in_offer_rm == 'F.O.R (Freight on Road)' || Thrie_SSDB_trans_in_offer_rm == 'F.O.R (Freight on Road)' || Thrie_DSSB_trans_in_offer_rm == 'F.O.R (Freight on Road)' || Thrie_DSDB_trans_in_offer_rm == 'F.O.R (Freight on Road)' || wb_natrax_trans_in_offer == 'F.O.R (Freight on Road)' || wb_alka_trans_in_offer == 'F.O.R (Freight on Road)' || wb_trans_trans_in_offer == 'F.O.R (Freight on Road)' || tb_natrax_trans_in_offer == 'F.O.R (Freight on Road)' || tb_alka_trans_in_offer == 'F.O.R (Freight on Road)' || ns_w_beam_section_trans_in_offer == 'F.O.R (Freight on Road)' || ns_thrie_beam_section_trans_in_offer == 'F.O.R (Freight on Road)' || rlw_graded_section_trans_in_offer == 'F.O.R (Freight on Road)' || rlw_non_graded_section_trans_in_offer == 'F.O.R (Freight on Road)' ||  a_s_trans_in_offer == 'F.O.R (Freight on Road)' || r_s_trans_in_offer == 'F.O.R (Freight on Road)' || acc_section_trans_in_offer == 'F.O.R (Freight on Road)' || misc_section_trans_in_offer == 'F.O.R (Freight on Road)' || add_misc_trans_in_offer == 'F.O.R (Freight on Road)') ? 'F.O.R (Freight on Road)' : 'Ex-works'",
      "options": [
        "Ex-works",
        "F.O.R (Freight on Road)"
      ]
    },
    {
      "apiName": "customer_address_folder",
      "label": "Customer Address",
      "type": "folder",
      "iconColor": "blue",
      "controllingField": "freight_incoterms",
      "controllingValues": [
        "*"
      ],
      "modalConfigsByValue": {
        "default": {
          "title": "CUSTOMER ADDRESS",
          "modalFields": [
            {
              "id": "billing_address",
              "label": "Billing Address",
              "expanded": true,
              "fields": [
                {
                  "apiName": "ba_street",
                  "label": "STREET",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingStreet@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_city",
                  "label": "CITY",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingCity@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_zip_code",
                  "label": "ZIP-CODE",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingPostalCode@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_state",
                  "label": "STATE",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingState@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_country",
                  "label": "COUNTRY",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@BillingCountry@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_phone",
                  "label": "PHONE NUMBER",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@Phone@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_email",
                  "label": "EMAIL",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@Email__c@@",
                  "colSpan": 12
                },
                {
                  "apiName": "ba_website",
                  "label": "WEBSITE",
                  "type": "text",
                  "readOnly": true,
                  "defaultValue": "@@Website@@",
                  "colSpan": 12
                },
                {
                  "apiName": "has_transportation_address",
                  "label": "TRANSPORTATION ADDRESS?",
                  "type": "checkbox",
                  "defaultValue": false,
                  "colSpan": 12
                }
              ]
            },
            {
              "id": "shipping_address_section",
              "label": "Shipping address",
              "expanded": true,
              "controllingField": "has_transportation_address",
              "controllingValues": [
                "true"
              ],
              "fields": [
                {
                  "apiName": "sa_street",
                  "label": "STREET",
                  "type": "text",
                  "colSpan": 12
                },
                {
                  "apiName": "sa_city",
                  "label": "CITY",
                  "type": "text",
                  "colSpan": 12
                },
                {
                  "apiName": "sa_zip_code",
                  "label": "ZIP-CODE",
                  "type": "text",
                  "colSpan": 12
                },
                {
                  "apiName": "sa_state",
                  "label": "STATE",
                  "type": "text",
                  "colSpan": 12
                },
                {
                  "apiName": "sa_country",
                  "label": "COUNTRY",
                  "type": "text",
                  "colSpan": 12
                }
              ]
            }
          ]
        }
      }
    },
    {
      "apiName": "terms_and_conditions_folder",
      "label": "Terms & Conditions",
      "type": "folder",
      "iconColor": "red",
      "controllingField": "freight_incoterms",
      "controllingValues": [
        "*"
      ],
      "modalConfigsByValue": {
        "default": {
          "title": "TERMS & CONDITIONS",
          "modalFields": [
            {
              "id": "tc_details",
              "label": "Terms & Condition Details",
              "expanded": true,
              "fields": [
                {
                  "apiName": "tc_validity_days",
                  "label": "Validity (days)",
                  "type": "number",
                  "defaultValue": 5,
                  "colSpan": 3
                },
                {
                  "apiName": "tc_special_note",
                  "label": "Special Note",
                  "type": "textarea",
                  "colSpan": 9
                }
              ]
            },
            {
              "id": "payment_terms_section",
              "label": "Payment Terms",
              "expanded": true,
              "fields": [
                {
                  "apiName": "tc_payment_terms_picklist",
                  "label": "PAYMENT TERMS",
                  "type": "picklist",
                  "defaultValue": "Advance",
                  "options": [
                    "Advance",
                    "Against LC",
                    "Against BG",
                    "Against Open Credit"
                  ],
                  "colSpan": 12
                },
                {
                  "apiName": "tc_no_of_days_interest_free_credit",
                  "label": "No. of days Interest free credit",
                  "type": "number",
                  "colSpan": 12,
                  "controllingField": "tc_payment_terms_picklist",
                  "controllingValues": [
                    "Against LC",
                    "Against BG",
                    "Against Open Credit"
                  ]
                },
                {
                  "apiName": "tc_rate_of_interest",
                  "label": "Rate of Interest %",
                  "type": "number",
                  "colSpan": 12,
                  "controllingField": "tc_payment_terms_picklist",
                  "controllingValues": [
                    "Against LC",
                    "Against BG",
                    "Against Open Credit"
                  ]
                },
                {
                  "apiName": "tc_usance_period",
                  "label": "Usance Period (Days)",
                  "type": "number",
                  "colSpan": 12,
                  "controllingField": "tc_payment_terms_picklist",
                  "controllingValues": [
                    "Against LC"
                  ]
                }
              ]
            }
          ]
        }
      }
    }
  ]
}
